import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Self-Evolving Multi-Agent Systems via Decentralized Memory (DecentMem)","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.22721","title":"Self-Evolving Multi-Agent Systems via Decentralized Memory (DecentMem)","affiliations":["University of Cambridge","University of Chicago"],"archived_date":"2026-06-18T00:00:00.000Z","arxiv_id":2605.22721,"authors":["Guangya Hao","Yunbo Long","Zhuokai Zhao"],"domains":["cs.MA"],"pdf_path":"pdfs/2605.22721.pdf","published_date":"2026-05-21T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-21-decentmem-self-evolving-mas-decentralized-memory-2605-22721.md","filePath":"research/papers/2026-05-21-decentmem-self-evolving-mas-decentralized-memory-2605-22721.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-05-21-decentmem-self-evolving-mas-decentralized-memory-2605-22721.md"};function s(i,e,l,c,d,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="self-evolving-multi-agent-systems-via-decentralized-memory-decentmem" tabindex="-1">Self-Evolving Multi-Agent Systems via Decentralized Memory (DecentMem) <a class="header-anchor" href="#self-evolving-multi-agent-systems-via-decentralized-memory-decentmem" aria-label="Permalink to &quot;Self-Evolving Multi-Agent Systems via Decentralized Memory (DecentMem)&quot;">​</a></h1><p><strong>Authors</strong>: Guangya Hao (Cambridge), Yunbo Long (Cambridge), Zhuokai Zhao (Chicago) <strong>Published</strong>: May 21, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.22721" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.22721</a><strong>arXiv ID</strong>: 2605.22721 <strong>Categories</strong>: cs.MA (Multiagent Systems) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.22721" target="_blank" rel="noreferrer">research/papers/pdfs/2605.22721.pdf</a> (27 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Self-evolving multi-agent systems (MAS) have emerged as a promising route to LLM agents that continually improve from experience, with persistent memory at their foundation. However, existing designs almost exclusively adopt a centralized repository shared across agents, incurring communication and coordination overhead, raising privacy concerns, and collapsing agent diversity. We propose DECENTMEM, a decentralized memory framework in which each agent maintains its own dual-pool memory — an exploitation pool of consolidated past trajectories and an exploration pool of LLM-generated candidates for unseen contexts. The two pools are reweighted online based on stage-wise feedback from an LLM-as-a-judge. Theoretically, we prove that this design guarantees global reachability of the solution space and achieves O(logT) cumulative regret, matching the stochastic bandit lower bound up to constants. In practice, across three MAS frameworks (AutoGen, DyLAN, AgentNet), three Qwen3 backbones (4B/8B/14B), two Gemma4 backbones (E2B/E4B) and five benchmarks spanning math, code, QA, and embodied tasks, DECENTMEM improves average accuracy by up to 23.8% over the strongest centralized memory baseline and by up to 52.5% over the no-memory baseline, while reducing token usage by up to 49%.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="問題陳述" tabindex="-1">問題陳述 <a class="header-anchor" href="#問題陳述" aria-label="Permalink to &quot;問題陳述&quot;">​</a></h3><p>集中式共享記憶池（centralized repository）為當前 self-evolving MAS 主流，但有四缺陷：通訊開銷、協調成本、隱私顧慮、<strong>agent 多樣性崩潰</strong>（所有 agent 收斂同一記憶表示 → 失去探索能力）。</p><h3 id="方法-§4-decentmem" tabindex="-1">方法（§4 DecentMem） <a class="header-anchor" href="#方法-§4-decentmem" aria-label="Permalink to &quot;方法（§4 DecentMem）&quot;">​</a></h3><ul><li><strong>雙池記憶（§4.1）</strong>：每 agent 獨立維護 <ul><li><em>Exploitation pool</em>：整合過去軌跡的鞏固記憶（reuse）</li><li><em>Exploration pool</em>：LLM 生成的候選，對應未見上下文</li></ul></li><li><strong>檢索（§4.2）</strong>：similarity search + threshold filtering，memory-conditioned solving</li><li><strong>更新（§4.3）</strong>：兩池權重由 <strong>LLM-as-a-judge</strong> 依 stage-wise feedback 線上 reweight，自動平衡 exploit/explore</li></ul><h3 id="理論保證-§5" tabindex="-1">理論保證（§5） <a class="header-anchor" href="#理論保證-§5" aria-label="Permalink to &quot;理論保證（§5）&quot;">​</a></h3><ul><li><strong>全局可達性（§5.2）</strong>：任何解都可被系統發現</li><li><strong>O(log T) 累積後悔（§5.3）</strong>：達 stochastic bandit 下界（至常數），理論最優</li><li>每 agent 獨立演化，不依賴全局協調</li></ul><h3 id="關鍵實驗結果-§6–7" tabindex="-1">關鍵實驗結果（§6–7） <a class="header-anchor" href="#關鍵實驗結果-§6–7" aria-label="Permalink to &quot;關鍵實驗結果（§6–7）&quot;">​</a></h3><p>實驗矩陣：3 MAS 框架（AutoGen / DyLAN / AgentNet）× 3 Qwen3（4B/8B/14B）× 2 Gemma4（E2B/E4B）× 5 benchmark（math/code/QA/embodied）。</p><ul><li><strong>vs 最強集中式基線</strong>：平均準確率 <strong>+23.8%</strong>，token <strong>-49%</strong>（同時達成，非取捨）</li><li><strong>vs 無記憶基線</strong>：<strong>+52.5%</strong></li><li>Cost analysis（§7.2）+ ablation（§7.3）支持雙池設計各自貢獻。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>subagent 記憶設計</strong>：本 workspace 所有 subagent 共享 <code>MEMORY.md</code>（集中式）；DecentMem 建議 per-agent-type 獨立記憶區塊（researcher/implementer/reviewer）。</li><li>⚠️ 適用性落差：DecentMem 的增益來自<strong>同一 task 上多輪 self-evolving MAS 跑同質 backbone</strong>；本 workspace 的 subagent 是<strong>單次 fan-out、異質任務、跨 session 人工 MEMORY</strong>——bandit regret 模型的前提（重複 trials、stationary reward）不直接成立。理論最優性 ≠ 對本 workspace 場景的最優性。</li><li><strong>memory-compactor 演化方向</strong>：可參考 exploitation/exploration 雙區塊壓縮，但需先驗證 workspace 是否真有「多樣性崩潰」病徵（目前無證據）。</li><li>列為需更多跨 session 數據才能評估的 P2 觀察項。</li></ul>',19)])])}const p=a(n,[["render",s]]);export{h as __pageData,p as default};
